    /* header */
    "brand.sub": { en: "The purpose of this platform is to ensure that every citizen has the opportunity to have their concerns or ideas heard by the nation.", es: "El prop\u00f3sito de esta plataforma es garantizar que cada ciudadano tenga la oportunidad de que sus inquietudes o ideas sean escuchadas por la naci\u00f3n." },


    "citizen.signedin": { en: "Signed in as", es: "Sesi\u00f3n iniciada como" },






