    "gate.hard": { en: "<strong>Cannot publish:</strong> this draft contains {spans}, which counts as profanity, a slur, or a personal attack. Such posts are never published. Remove it and keep your address professional.", es: "<strong>No se puede publicar:</strong> este borrador contiene {spans}, lo cual cuenta como blasfemia, insulto o ataque personal. Tales publicaciones nunca se publican. Elim\u00ednalo y mant\u00e9n un tono profesional." },
    "gate.soft": { en: "<strong>Held for your correction:</strong> {n} wording issue(s) do not meet the formal standard for a national address. Accept a suggestion or retype the word yourself \u2014 nothing changes without your action.", es: "<strong>Retenido para tu correcci\u00f3n:</strong> {n} problema(s) de redacci\u00f3n no cumplen el est\u00e1ndar formal de un discurso nacional. Acepta una sugerencia o reescribe la palabra t\u00fa mismo \u2014 nada cambia sin tu acci\u00f3n." },
