    /* briefing */
    "briefing.aria": { en: "Weekly briefing", es: "Sesi\u00f3n informativa semanal" },
    "briefing.title": { en: "This week\u2019s briefing \u2014 {date}", es: "La sesi\u00f3n de esta semana \u2014 {date}" },
    "briefing.lede1": { en: "Two posts take up most of the segment: the highest-voted post and one post drawn at random. Both are read aloud verbatim and answered. Follow-ups on earlier posts get only a brief live mention; the full record lives under Prior Posts & Answers and Status Updates.", es: "Dos publicaciones ocupan la mayor parte del segmento: la publicaci\u00f3n m\u00e1s votada y una publicaci\u00f3n elegida al azar. Ambas se leen en voz alta textualmente y se responden. Los seguimientos de publicaciones anteriores solo reciben una breve menci\u00f3n en directo; el registro completo est\u00e1 en Publicaciones y respuestas anteriores y Actualizaciones de estado." },
    "briefing.lede2": { en: "The weekly schedule (all times ET): posting and voting week Monday 00:00 \u2192 Sunday 23:59; cutoff Sunday 23:59, when the eligible pool is frozen and published; draw Monday 12:00, pre-announced; committee week Monday \u2192 Sunday to evaluate both selected posts and formulate both answers \u2014 answers ONLY, it can never alter, substitute, delay, or decline a selection; briefing Wednesday 1:00 PM. The Podium segment is the fixed opening segment of the Wednesday briefing: if no regular briefing is scheduled that Wednesday, the segment still runs on its own at the same time.", es: "El horario semanal (todas las horas ET): semana de publicaci\u00f3n y votaci\u00f3n de lunes 00:00 \u2192 domingo 23:59; corte el domingo 23:59, cuando el grupo elegible se congela y se publica; sorteo el lunes 12:00, preanunciado; semana del comit\u00e9 de lunes \u2192 domingo para evaluar ambas publicaciones seleccionadas y formular ambas respuestas \u2014 solo respuestas, nunca puede alterar, sustituir, retrasar ni rechazar una selecci\u00f3n; sesi\u00f3n el mi\u00e9rcoles 1:00 PM. El segmento de The Podium es el segmento fijo de apertura de la sesi\u00f3n del mi\u00e9rcoles: si no hay sesi\u00f3n ordinaria programada ese mi\u00e9rcoles, el segmento se realiza por su cuenta a la misma hora." },
    "briefing.watch": { en: "Watch Live \u2192", es: "Ver en vivo \u2192" },
    "briefing.watch.hint": { en: "Attend the airing of this briefing.", es: "Asiste a la emisi\u00f3n de esta sesi\u00f3n." },
    "briefing.next": { en: "Next Week", es: "La pr\u00f3xima semana" },
    "briefing.next.hint": { en: "Selected posts in committee review. Answers are still being formulated \u2014 never presented as final. These selections are published after the Monday draw, once the draw has selected the posts: the full posts for the next briefing appear here from the draw onward, in full, with approved answers published as soon as the committee approves them.", es: "Publicaciones seleccionadas en revisi\u00f3n del comit\u00e9. Las respuestas a\u00fan se est\u00e1n formulando \u2014 nunca se presentan como definitivas. Estas selecciones se publican despu\u00e9s del sorteo del lunes, una vez que el sorteo ha elegido las publicaciones: las publicaciones completas para la pr\u00f3xima sesi\u00f3n aparecen aqu\u00ed desde el sorteo en adelante, \u00edntegras, con las respuestas aprobadas publicadas en cuanto el comit\u00e9 las apruebe." },
    "briefing.draw": { en: "The random draw \u2014 verifiably fair", es: "El sorteo aleatorio \u2014 verificablemente justo" },
    "briefing.draw.lede": { en: "The eligible pool is frozen and published <em>first</em> (all posts that passed the wording check since the last draw, minus the top-voted winner). The system runs the draw at the pre-announced time: <code>position = beacon value modulo the pool size + 1</code>. Random selection is conducted using the NIST Randomness Beacon.", es: "El grupo elegible se congela y se publica <em>primero</em> (todas las publicaciones que pasaron la revisi\u00f3n de redacci\u00f3n desde el \u00faltimo sorteo, menos la ganadora m\u00e1s votada). El sistema ejecuta el sorteo a la hora preanunciada: <code>posici\u00f3n = valor del faro m\u00f3dulo el tama\u00f1o del grupo + 1</code>. Selecci\u00f3n aleatoria realizada con el Faro de Aleatoriedad del NIST." },
    "briefing.draw.excluded": { en: "Excluded from the pool", es: "Excluidas del grupo" },
    "briefing.draw.readonly": { en: "Record of the draw: pool size, beacon timestamp and value, computed position, and the drawn post. The draw runs once, internally \u2014 nothing here re-runs it.", es: "Registro del sorteo: tama\u00f1o del grupo, marca de tiempo y valor del faro, posici\u00f3n calculada y la publicaci\u00f3n sorteada. El sorteo se ejecuta una vez, de forma interna \u2014 nada aqu\u00ed lo repite." },
    "briefing.draw.worked": { en: "Worked example", es: "Ejemplo pr\u00e1ctico" },
    "briefing.draw.worked.body": { en: "Pool of 12, beacon value ending \u20264839 \u2192 4839 mod 12 = 3 \u2192 +1 = <strong>post #4</strong>.", es: "Grupo de 12, valor del faro terminado en \u20264839 \u2192 4839 mod 12 = 3 \u2192 +1 = <strong>publicaci\u00f3n n.\u00ba 4</strong>." },
    "briefing.draw.committee": { en: "Committee rule: the committee prepares answers ONLY. It can never alter, substitute, delay, or decline a selected post. It has one week to formulate an answer and route the topic to the right branch or level of government.", es: "Regla del comit\u00e9: el comit\u00e9 prepara respuestas SOLAMENTE. Nunca puede alterar, sustituir, retrasar ni rechazar una publicaci\u00f3n seleccionada. Tiene una semana para formular una respuesta y dirigir el tema a la rama o al nivel de gobierno correctos." },
    "draw.cycle": { en: "Cycle", es: "Ciclo" },
    "draw.frozen": { en: "Pool frozen", es: "Grupo congelado" },
    "draw.frozen.val": { en: "{cutoff} \u2014 {n} eligible posts (winner and winner-matching copies excluded), published before the draw", es: "{cutoff} \u2014 {n} publicaciones elegibles (excluidas la ganadora y sus copias), publicadas antes del sorteo" },
